[CmdletBinding()]
param(
    [ValidateSet("stable", "nightly")]
    [string] $Channel = "stable",

    [ValidateNotNullOrEmpty()]
    [string] $InstallDir = (Join-Path $HOME ".local\bin"),

    [switch] $NoPathUpdate,

    [Alias("h")]
    [switch] $Help
)

# Keep all installer functions and preference changes in a child scope. This
# matters when the script is piped to Invoke-Expression in an existing shell.
# Path is empty under irm | iex; pass it in so the child can tell file vs pipe
# without leaking a variable into the caller's session.
& {
    param(
        [string] $SelectedChannel,
        [string] $SelectedInstallDir,
        [bool] $SkipPathUpdate,
        [bool] $ShowHelp,
        [bool] $InvokedFromFile
    )

    Set-StrictMode -Version 2.0
    $ErrorActionPreference = "Stop"
    $ProgressPreference = "SilentlyContinue"

    $GitHubRepo = "entireio/cli"
    $ScoopBucketUrl = "https://github.com/entireio/scoop-bucket.git"

    function Write-Info {
        param([string] $Message)
        Write-Host "==> $Message" -ForegroundColor Cyan
    }

    function Write-Success {
        param([string] $Message)
        Write-Host "==> $Message" -ForegroundColor Green
    }

    function Write-InstallerWarning {
        param([string] $Message)
        Write-Host "Warning: $Message" -ForegroundColor Yellow
    }

    function Write-Usage {
        Write-Host @"
Usage: install.ps1 [-Channel stable|nightly] [-InstallDir <path>] [-NoPathUpdate]

Options:
  -Channel       Release channel to install (default: stable)
  -InstallDir    Direct-install destination (default: `$HOME\.local\bin)
  -NoPathUpdate  Do not add a direct-install destination to the user PATH
  -Help, -h      Show this help message

Stable installs use Scoop when it is available. Nightly installs use the
verified release archive because the Scoop bucket only publishes stable builds.
"@
    }

    function Install-EntireWithScoop {
        Write-Info "Scoop detected; installing Entire CLI with Scoop..."

        $bucketOutput = & "scoop" bucket list 2>&1
        $bucketExitCode = $LASTEXITCODE
        if ($bucketExitCode -ne 0) {
            $details = ($bucketOutput | Out-String).Trim()
            throw "Failed to list Scoop buckets. $details"
        }

        $bucketList = $bucketOutput | Out-String
        if ($bucketList -notmatch "(?im)^\s*entire(?:\s|$)") {
            Write-Info "Adding the Entire Scoop bucket..."
            & "scoop" bucket add entire $ScoopBucketUrl
            if ($LASTEXITCODE -ne 0) {
                throw "Failed to add the Entire Scoop bucket."
            }
        }

        & "scoop" prefix entire *> $null
        $isInstalled = $LASTEXITCODE -eq 0
        if ($isInstalled) {
            Write-Info "Updating Entire CLI with Scoop..."
            & "scoop" update entire/entire
        }
        else {
            Write-Info "Installing Entire CLI with Scoop..."
            & "scoop" install entire/entire
        }

        if ($LASTEXITCODE -ne 0) {
            throw "Scoop failed to install Entire CLI."
        }

        Write-Success "Entire CLI installed with Scoop"
    }

    function Get-PlatformArchitecture {
        # PROCESSOR_ARCHITEW6432 identifies the native OS architecture when
        # this script is running in a 32-bit PowerShell process.
        $architecture = $env:PROCESSOR_ARCHITEW6432
        if ([string]::IsNullOrWhiteSpace($architecture)) {
            $architecture = $env:PROCESSOR_ARCHITECTURE
        }

        if ([string]::IsNullOrWhiteSpace($architecture)) {
            throw "Cannot determine the Windows architecture."
        }

        switch ($architecture.ToUpperInvariant()) {
            { $_ -in @("AMD64", "X86_64") } { return "amd64" }
            { $_ -in @("ARM64", "AARCH64") } { return "arm64" }
            default { throw "Unsupported architecture: $architecture" }
        }
    }

    function Invoke-GitHubApi {
        param([string] $Uri)

        $headers = @{
            "Accept"     = "application/vnd.github+json"
            "User-Agent" = "entire-install.ps1"
        }
        if (-not [string]::IsNullOrWhiteSpace($env:GITHUB_TOKEN)) {
            $headers["Authorization"] = "Bearer $($env:GITHUB_TOKEN)"
        }

        Invoke-RestMethod -Uri $Uri -Headers $headers
    }

    function Get-ReleaseVersion {
        param([string] $ReleaseChannel)

        if ($ReleaseChannel -eq "nightly") {
            $uri = "https://api.github.com/repos/$GitHubRepo/releases?per_page=20"
            $releases = Invoke-GitHubApi -Uri $uri
            $release = $null

            # Windows PowerShell 5.1 returns a JSON array from
            # Invoke-RestMethod as one pipeline object. A Where-Object pipeline
            # would therefore test the whole release list at once instead of
            # each release, so enumerate it explicitly.
            foreach ($candidate in $releases) {
                if ($candidate.tag_name -like "*nightly*") {
                    $release = $candidate
                    break
                }
            }
        }
        else {
            $uri = "https://api.github.com/repos/$GitHubRepo/releases/latest"
            $release = Invoke-GitHubApi -Uri $uri
        }

        if ($null -eq $release -or [string]::IsNullOrWhiteSpace([string] $release.tag_name)) {
            throw "Failed to fetch the latest $ReleaseChannel version from GitHub. Check your internet connection."
        }

        $version = ([string] $release.tag_name) -replace "^v", ""
        if ($version -notmatch "^[0-9]+\.[0-9]+\.[0-9]+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$") {
            throw "GitHub returned an invalid release version: $version"
        }

        return $version
    }

    function Save-RemoteFile {
        param(
            [string] $Uri,
            [string] $Destination
        )

        # -UseBasicParsing is required for Windows PowerShell 5.1 (skips the IE
        # DOM parser). In PowerShell 7+ it is accepted and silently ignored.
        Invoke-WebRequest -Uri $Uri -OutFile $Destination -UseBasicParsing
    }

    function Assert-Checksum {
        param(
            [string] $ArchivePath,
            [string] $ArchiveName,
            [string] $ChecksumsPath
        )

        $escapedArchiveName = [regex]::Escape($ArchiveName)
        $checksumLine = Get-Content -LiteralPath $ChecksumsPath |
            Where-Object { $_ -match "(?i)^[0-9a-f]{64}\s+\*?$escapedArchiveName\s*$" } |
            Select-Object -First 1

        if ([string]::IsNullOrWhiteSpace([string] $checksumLine)) {
            throw "Checksum for $ArchiveName was not found in checksums.txt."
        }

        $expectedChecksum = ([string] $checksumLine -split "\s+")[0]
        $actualChecksum = (Get-FileHash -LiteralPath $ArchivePath -Algorithm SHA256).Hash
        if (-not [string]::Equals($actualChecksum, $expectedChecksum, [StringComparison]::OrdinalIgnoreCase)) {
            throw "Checksum verification failed. Expected: $expectedChecksum, actual: $actualChecksum"
        }
    }

    function Get-NormalizedPath {
        param([string] $Path)

        return [IO.Path]::GetFullPath($Path).TrimEnd([IO.Path]::DirectorySeparatorChar)
    }

    function Test-SamePath {
        param(
            [string] $Left,
            [string] $Right
        )

        if ([string]::IsNullOrWhiteSpace($Left) -or [string]::IsNullOrWhiteSpace($Right)) {
            return $false
        }

        try {
            return [string]::Equals(
                (Get-NormalizedPath -Path $Left),
                (Get-NormalizedPath -Path $Right),
                [StringComparison]::OrdinalIgnoreCase
            )
        }
        catch {
            return $false
        }
    }

    function Test-PathContains {
        param(
            [AllowNull()]
            [string] $PathValue,
            [string] $Directory
        )

        if ([string]::IsNullOrWhiteSpace($PathValue)) {
            return $false
        }

        foreach ($entry in ($PathValue -split ";")) {
            if (Test-SamePath -Left $entry.Trim() -Right $Directory) {
                return $true
            }
        }
        return $false
    }

    function Add-ToUserPath {
        param([string] $Directory)

        $userPath = [Environment]::GetEnvironmentVariable("Path", "User")
        if (-not (Test-PathContains -PathValue $userPath -Directory $Directory)) {
            if ([string]::IsNullOrWhiteSpace($userPath)) {
                $newUserPath = $Directory
            }
            else {
                $newUserPath = "$Directory;$userPath"
            }
            [Environment]::SetEnvironmentVariable("Path", $newUserPath, "User")
        }

        # Make the command available immediately when install.ps1 is evaluated
        # in the caller's current PowerShell process.
        if (-not (Test-PathContains -PathValue $env:Path -Directory $Directory)) {
            $env:Path = "$Directory;$($env:Path)"
        }
    }

    function Get-EntireOnPath {
        # -All is required: without it Get-Command returns only the first
        # Application, so a later Scoop shim is never seen.
        return @(Get-Command "entire" -CommandType Application -All -ErrorAction SilentlyContinue)
    }

    function Install-Entire {
        if ($ShowHelp) {
            Write-Usage
            return
        }

        Write-Info "Installing Entire CLI..."

        $scoopCommand = Get-Command "scoop" -ErrorAction SilentlyContinue
        if ($SelectedChannel -eq "stable" -and $null -ne $scoopCommand) {
            Install-EntireWithScoop
            return
        }
        if ($SelectedChannel -eq "nightly" -and $null -ne $scoopCommand) {
            Write-InstallerWarning "Scoop only publishes stable releases; installing nightly from the verified release archive."
        }

        $resolvedInstallDir = Get-NormalizedPath -Path $SelectedInstallDir
        $installPath = Join-Path $resolvedInstallDir "entire.exe"

        # Match install.sh: abort if another entire wins on PATH. Check before
        # copying so a conflict does not leave files behind.
        $pathCommands = Get-EntireOnPath
        $conflicting = @($pathCommands | Where-Object { -not (Test-SamePath -Left $_.Source -Right $installPath) })
        if ($conflicting.Count -gt 0) {
            $first = $pathCommands | Select-Object -First 1
            $firstIsOurs = Test-SamePath -Left $first.Source -Right $installPath
            Write-Host ""
            Write-Host "! WARNING: PATH conflict detected" -ForegroundColor Yellow
            Write-Host "!"
            Write-Host "! Install destination: $installPath"
            foreach ($cmd in $conflicting) {
                Write-Host "! Also found:   $($cmd.Source)"
            }
            if (-not $firstIsOurs) {
                Write-Host "!"
                Write-Host "! 'entire' currently resolves to: $($first.Source)"
                Write-Host "! Remove the old installation or adjust PATH to prioritize:"
                Write-Host "!   $resolvedInstallDir"
                Write-Host ""
                throw "PATH needs adjustment. Then rerun the installation."
            }
            Write-Host "!"
            Write-Host "! The installed version takes priority, but consider removing"
            Write-Host "! the other installation to avoid confusion."
            Write-Host ""
        }

        # GitHub requires TLS 1.2. Use the numeric value so this remains valid
        # on .NET versions whose SecurityProtocolType enum omits the name.
        [Net.ServicePointManager]::SecurityProtocol =
            [Net.ServicePointManager]::SecurityProtocol -bor 3072

        $architecture = Get-PlatformArchitecture
        Write-Info "Detected platform: windows/$architecture"

        Write-Info "Fetching latest $SelectedChannel version..."
        $version = Get-ReleaseVersion -ReleaseChannel $SelectedChannel
        Write-Info "Installing version: $version"

        $archiveName = "entire_windows_$architecture.zip"
        $releaseBaseUrl = "https://github.com/$GitHubRepo/releases/download/v$version"
        $downloadUrl = "$releaseBaseUrl/$archiveName"
        $checksumsUrl = "$releaseBaseUrl/checksums.txt"

        $tempDir = Join-Path ([IO.Path]::GetTempPath()) ("entire-install-" + [guid]::NewGuid().ToString("N"))
        New-Item -ItemType Directory -Path $tempDir | Out-Null

        try {
            $archivePath = Join-Path $tempDir $archiveName
            $checksumsPath = Join-Path $tempDir "checksums.txt"
            $extractDir = Join-Path $tempDir "extracted"

            Write-Info "Downloading $archiveName..."
            Save-RemoteFile -Uri $downloadUrl -Destination $archivePath

            Write-Info "Downloading checksums..."
            Save-RemoteFile -Uri $checksumsUrl -Destination $checksumsPath

            Write-Info "Verifying checksum..."
            Assert-Checksum -ArchivePath $archivePath -ArchiveName $archiveName -ChecksumsPath $checksumsPath
            Write-Success "Checksum verified"

            Write-Info "Extracting..."
            Expand-Archive -LiteralPath $archivePath -DestinationPath $extractDir -Force

            $sourceBinary = Join-Path $extractDir "entire.exe"
            $sourceHelper = Join-Path $extractDir "git-remote-entire.exe"
            if (-not (Test-Path -LiteralPath $sourceBinary -PathType Leaf)) {
                throw "entire.exe was not found in $archiveName."
            }

            Write-Info "Installing to $resolvedInstallDir..."
            New-Item -ItemType Directory -Path $resolvedInstallDir -Force | Out-Null

            Copy-Item -LiteralPath $sourceBinary -Destination $installPath -Force

            if (Test-Path -LiteralPath $sourceHelper -PathType Leaf) {
                Copy-Item -LiteralPath $sourceHelper -Destination (Join-Path $resolvedInstallDir "git-remote-entire.exe") -Force
            }
            else {
                Write-InstallerWarning "git-remote-entire.exe was not found in the archive; entire:// clones will not work until the next release includes it."
            }

            & $installPath version *> $null
            if ($LASTEXITCODE -ne 0) {
                throw "Installation completed, but entire.exe failed to execute."
            }
            Write-Success "Entire CLI installed to $installPath"

            if ($SkipPathUpdate) {
                if ($pathCommands.Count -eq 0) {
                    Write-InstallerWarning "$resolvedInstallDir is not on PATH. Add it before running entire."
                }
            }
            else {
                Add-ToUserPath -Directory $resolvedInstallDir
                if ($pathCommands.Count -eq 0) {
                    Write-Success "Added $resolvedInstallDir to your user PATH"
                    Write-Host "Restart your terminal, then run entire to get started."
                }
            }
        }
        finally {
            Remove-Item -LiteralPath $tempDir -Recurse -Force -ErrorAction SilentlyContinue
        }
    }

    try {
        Install-Entire
    }
    catch {
        $message = "Error: $($_.Exception.Message)"
        if ($InvokedFromFile) {
            Write-Host $message -ForegroundColor Red
            exit 1
        }
        # irm | iex: throw without Write-Host so the message appears once, and
        # do not exit 1 — that would close the user's interactive shell.
        throw $message
    }
} $Channel $InstallDir $NoPathUpdate.IsPresent $Help.IsPresent (-not [string]::IsNullOrEmpty($MyInvocation.MyCommand.Path))
package versioncheck

import (
	"context"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"net/http"
	"os"
	"path/filepath"
	"runtime"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/logging"
	"github.com/entireio/cli/cmd/entire/cli/versioninfo"
	"github.com/entireio/cli/internal/entireclient/userdirs"
	"golang.org/x/mod/module"
	"golang.org/x/mod/semver"
)

const goosWindows = "windows"

// goos is a test seam for runtime.GOOS so the Windows-specific auto-install
// gating can be exercised from a non-Windows host.
var goos = runtime.GOOS

const (
	installManagerBrew    = "brew"
	installManagerMise    = "mise"
	installManagerScoop   = "scoop"
	installManagerUnknown = "unknown"
	installChannelStable  = "stable"
	installChannelNightly = "nightly"
)

// CheckAndNotify performs a version check and notifies the user if a newer version is available.
// This is the main entry point for the version check system.
// The function is silent on all errors to avoid interrupting CLI operations.
func CheckAndNotify(ctx context.Context, w io.Writer, currentVersion string) {
	// Skip checks for local/unreleased builds.
	if isDevBuild(currentVersion) {
		return
	}

	// Ensure the global config directory exists
	if err := ensureGlobalConfigDir(); err != nil {
		// Silent failure - don't block CLI operations
		return
	}

	// Load the cache to check when we last fetched
	cache, err := loadCache()
	if err != nil {
		cache = &VersionCache{}
	}

	// Skip if we checked recently (within 24 hours)
	if time.Since(cache.LastCheckTime) < checkInterval {
		return
	}

	// Fetch the latest version from the appropriate channel
	var latestVersion string
	if isNightly(currentVersion) {
		latestVersion, err = fetchLatestNightlyVersion(ctx)
	} else {
		latestVersion, err = fetchLatestVersion(ctx)
	}

	// Always update cache to avoid retrying on every CLI invocation
	cache.LastCheckTime = time.Now()
	if saveErr := saveCache(cache); saveErr != nil {
		logging.Debug(ctx, "version check: failed to save cache",
			"error", saveErr.Error())
	}

	if err != nil {
		logging.Debug(ctx, "version check: failed to fetch latest version",
			"error", err.Error())
		return
	}

	// Show notification and offer an interactive upgrade when outdated
	if isOutdated(currentVersion, latestVersion) {
		if cache.SkippedVersion == versionCacheKey(latestVersion) {
			return
		}

		action := MaybeAutoUpdate(ctx, w, currentVersion, latestVersion)
		if action == autoUpdateActionSkipUntilNextVersion {
			cache.SkippedVersion = versionCacheKey(latestVersion)
			if saveErr := saveCache(cache); saveErr != nil {
				logging.Debug(ctx, "version check: failed to save skipped version",
					"error", saveErr.Error())
			}
		}
	}
}

// globalConfigDirPath returns the CLI's global config directory. Resolution
// lives in userdirs.Config — the single implementation shared by all
// config-dir consumers (contexts.json, the file token store, this cache).
func globalConfigDirPath() string {
	return userdirs.Config()
}

// ensureGlobalConfigDir creates the global config directory if it doesn't exist.
//
// It goes through userdirs.EnsurePrivateDir rather than MkdirAll because this
// directory is shared with contexts.json and the file token store, both of
// which hold bearer tokens. The version check runs from the root command's
// PersistentPostRun, so on a fresh machine it is almost always what creates
// the directory — before the first login ever runs. Creating it world-readable
// here left it that way permanently, since the credential stores' own
// MkdirAll(0700) cannot change the mode of a directory that already exists.
func ensureGlobalConfigDir() error {
	if err := userdirs.EnsurePrivateDir(globalConfigDirPath()); err != nil {
		return fmt.Errorf("creating config directory: %w", err)
	}

	return nil
}

// cacheFilePath returns the full path to the version check cache file.
func cacheFilePath() string {
	return filepath.Join(globalConfigDirPath(), cacheFileName)
}

// loadCache loads the version check cache from disk.
// Returns an error if the file doesn't exist or is corrupted.
func loadCache() (*VersionCache, error) {
	data, err := os.ReadFile(cacheFilePath())
	if err != nil {
		return nil, fmt.Errorf("reading cache file: %w", err)
	}

	var cache VersionCache
	if err := json.Unmarshal(data, &cache); err != nil {
		return nil, fmt.Errorf("parsing cache: %w", err)
	}

	return &cache, nil
}

// saveCache saves the version check cache to disk.
// Uses atomic write semantics (write to temp file, then rename).
func saveCache(cache *VersionCache) error {
	filePath := cacheFilePath()

	// Marshal to JSON
	data, err := json.MarshalIndent(cache, "", "  ")
	if err != nil {
		return fmt.Errorf("marshaling cache: %w", err)
	}

	// Write to temp file first (atomic write)
	dir := filepath.Dir(filePath)
	tmpFile, err := os.CreateTemp(dir, ".version_check_tmp_")
	if err != nil {
		return fmt.Errorf("creating temp file: %w", err)
	}
	defer os.Remove(tmpFile.Name())

	if _, err := tmpFile.Write(data); err != nil {
		_ = tmpFile.Close() // cleanup on error path
		return fmt.Errorf("writing cache: %w", err)
	}

	if err := tmpFile.Close(); err != nil {
		return fmt.Errorf("closing temp file: %w", err)
	}

	// Rename temp file to final location

	if err := os.Rename(tmpFile.Name(), filePath); err != nil {
		return fmt.Errorf("renaming cache file: %w", err)
	}

	return nil
}

// fetchLatestVersion fetches the latest stable version tag from the GitHub API.
func fetchLatestVersion(ctx context.Context) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubAPIURL, nil)
	if err != nil {
		return "", fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", versioninfo.UserAgent())

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetching release info: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", fmt.Errorf("reading response: %w", err)
	}

	version, err := parseGitHubRelease(body)
	if err != nil {
		return "", fmt.Errorf("parsing release: %w", err)
	}
	return version, nil
}

// isNightly returns true if the version string is a nightly build.
func isNightly(version string) bool {
	if !strings.HasPrefix(version, "v") {
		version = "v" + version
	}
	return strings.Contains(semver.Prerelease(version), "nightly")
}

// fetchLatestNightlyVersion fetches the latest nightly version tag from the GitHub releases list.
func fetchLatestNightlyVersion(ctx context.Context) (string, error) {
	ctx, cancel := context.WithTimeout(ctx, httpTimeout)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, githubReleasesURL+"?per_page=20", nil)
	if err != nil {
		return "", fmt.Errorf("creating request: %w", err)
	}

	req.Header.Set("Accept", "application/vnd.github+json")
	req.Header.Set("User-Agent", versioninfo.UserAgent())

	client := &http.Client{}
	resp, err := client.Do(req)
	if err != nil {
		return "", fmt.Errorf("fetching releases: %w", err)
	}
	defer resp.Body.Close()

	if resp.StatusCode != http.StatusOK {
		return "", fmt.Errorf("unexpected status code: %d", resp.StatusCode)
	}

	body, err := io.ReadAll(io.LimitReader(resp.Body, 1<<20))
	if err != nil {
		return "", fmt.Errorf("reading response: %w", err)
	}

	var releases []GitHubRelease
	if err := json.Unmarshal(body, &releases); err != nil {
		return "", fmt.Errorf("parsing JSON: %w", err)
	}

	for _, r := range releases {
		if r.Prerelease && strings.Contains(r.TagName, "-nightly.") {
			return r.TagName, nil
		}
	}

	return "", errors.New("no nightly release found")
}

// parseGitHubRelease parses the GitHub API response and returns the latest stable version tag.
// Filters out prerelease versions.
func parseGitHubRelease(body []byte) (string, error) {
	var release GitHubRelease
	if err := json.Unmarshal(body, &release); err != nil {
		return "", fmt.Errorf("parsing JSON: %w", err)
	}

	if release.Prerelease {
		return "", errors.New("only prerelease versions available")
	}

	if release.TagName == "" {
		return "", errors.New("empty tag name")
	}

	return release.TagName, nil
}

// isOutdated compares current and latest versions using semantic versioning.
// Returns true if current < latest.
func isOutdated(current, latest string) bool {
	// Ensure versions have "v" prefix for semver package
	if !strings.HasPrefix(current, "v") {
		current = "v" + current
	}
	if !strings.HasPrefix(latest, "v") {
		latest = "v" + latest
	}

	// Local/unreleased builds shouldn't trigger update notifications.
	// Normal prereleases (e.g., "1.0.0-rc1") should still be compared normally.
	if isDevBuild(current) {
		return false
	}

	// semver.Compare returns -1 if current < latest
	return semver.Compare(current, latest) < 0
}

// isDevBuild reports whether v identifies a local, unreleased build that
// should not be nagged to update. This covers the "dev" sentinel and empty
// string (an unstamped binary), a Go pseudo-version (built from a commit that
// isn't a tagged release), and any build carrying +metadata such as "+dirty".
// Released builds — stable tags, nightly tags, and `go install ...@<tag>` —
// have clean semver and return false.
func isDevBuild(v string) bool {
	if v == "" || v == "dev" {
		return true
	}
	if !strings.HasPrefix(v, "v") {
		v = "v" + v
	}
	return !semver.IsValid(v) || module.IsPseudoVersion(v) || semver.Build(v) != ""
}

func versionCacheKey(version string) string {
	if version == "" || strings.HasPrefix(version, "v") {
		return version
	}
	return "v" + version
}

func displayVersion(version string) string {
	return strings.TrimPrefix(version, "v")
}

func releaseNotesURL(version string) string {
	return downloadsURL + "/tag/" + versionCacheKey(version)
}

// executablePath is the function used to get the current executable path.
// It's a variable so tests can override it.
var executablePath = os.Executable

func releaseChannel(version string) string {
	if isNightly(version) {
		return installChannelNightly
	}
	return installChannelStable
}

// normalizedExecPath returns the running binary's real path with all separators
// normalized to forward slashes (symlinks resolved, best-effort). Both the
// install-manager detection and the Scoop app-dir lookup key off this form.
func normalizedExecPath() (string, error) {
	execPath, err := executablePath()
	if err != nil {
		return "", err
	}
	realPath, err := filepath.EvalSymlinks(execPath)
	if err != nil {
		realPath = execPath
	}
	return strings.ReplaceAll(filepath.ToSlash(realPath), "\\", "/"), nil
}

// scoopAppName returns the Scoop app directory the running binary lives under
// — the path segment after `/scoop/apps/` (e.g. "cli" or "entire") — or ""
// when the binary is not a Scoop install. This is the durable signal for the
// pre-rename package: a binary running from the `cli` app dir must migrate to
// `entire` regardless of its version (the fix ships in a final `cli` release,
// so the migrating binary's version is already past the rename).
func scoopAppName() string {
	normalized, err := normalizedExecPath()
	if err != nil {
		return ""
	}
	_, rest, ok := strings.Cut(normalized, "/scoop/apps/")
	if !ok {
		return ""
	}
	// Cut returns the whole string when the separator is absent, so this covers
	// both `.../scoop/apps/cli/current/entire.exe` and a bare app segment.
	app, _, _ := strings.Cut(rest, "/")
	return app
}

func installManagerForCurrentBinary() string {
	normalizedPath, err := normalizedExecPath()
	if err != nil {
		return installManagerUnknown
	}

	switch {
	case strings.Contains(normalizedPath, "/Cellar/") ||
		strings.Contains(normalizedPath, "/opt/homebrew/") ||
		strings.Contains(normalizedPath, "/linuxbrew/") ||
		strings.Contains(normalizedPath, "/Caskroom/"):
		return installManagerBrew
	case strings.Contains(normalizedPath, "/mise/installs/"):
		return installManagerMise
	case strings.Contains(normalizedPath, "/scoop/apps/"):
		return installManagerScoop
	default:
		return installManagerUnknown
	}
}

// canAutoInstall reports whether updateCommand(currentVersion) is safe to
// execute on the current OS. Returns false on Windows when the install
// manager is unknown, because the POSIX curl-pipe-bash fallback can't run
// from cmd.exe and there's no Windows-native installer to substitute.
func canAutoInstall() bool {
	if goos != goosWindows {
		return true
	}
	switch installManagerForCurrentBinary() {
	case installManagerScoop, installManagerMise:
		return true
	default:
		return false
	}
}

// downloadsURL is the public page users visit when we can't offer an
// auto-installable command on their platform.
const downloadsURL = "https://github.com/entireio/cli/releases"

// updateCommand returns the appropriate update instruction based on how the binary was installed.
func updateCommand(currentVersion string) string {
	switch installManagerForCurrentBinary() {
	case installManagerBrew:
		if releaseChannel(currentVersion) == installChannelNightly {
			return "brew upgrade --yes entire@nightly"
		}
		return "brew upgrade --yes entire"
	case installManagerMise:
		return "mise upgrade entire"
	case installManagerScoop:
		// The Scoop package was renamed from `cli` to `entire`. A binary still
		// running from the old `cli` app dir can never cross the rename with a
		// plain `scoop update entire/cli`, so migrate it: install the new
		// `entire` package, remove the old `cli` package, then reset the shared
		// shims. Both manifests declare `bin: [git-remote-entire.exe,
		// entire.exe]`, so the two packages contend for the same shims. Current
		// Scoop handles that itself: installing `entire` renames the displaced
		// shim to `entire.shim.cli` (warn_on_overwrite) and uninstalling `cli`
		// removes only that suffixed copy (rm_shim), leaving the active shims
		// pointing at `entire`. The reset step is belt-and-braces for older
		// Scoop versions that overwrote shims without that alt-file dance and
		// would otherwise take `entire.exe` and the git remote helper with them.
		//
		// The Windows updater is print-only, so return a self-contained command
		// users can paste into either cmd or PowerShell. Explicitly invoking
		// cmd.exe makes `&&` portable across those shells and ensures uninstall
		// only runs after install succeeds — a stale bucket or transient failure
		// therefore never removes the working CLI. (The uninstall→reset link is
		// weaker: `scoop uninstall` ends in an unconditional `exit 0`, so reset
		// runs even when the uninstall skipped its work. That is harmless, since
		// reset is a no-op on the Scoop versions that make it unnecessary.)
		//
		// `scoop install` also auto-refreshes the bucket when >3h stale
		// (is_scoop_outdated), so the new manifest usually lands
		// without an explicit refresh; a bucket clone older than that check can
		// still fail with "couldn't find manifest", and the README migration
		// section names `scoop update` as the retry. Binaries already on the
		// `entire` app just update in place.
		if scoopAppName() == "cli" {
			return `cmd.exe /D /C "scoop install entire/entire && scoop uninstall entire/cli && scoop reset entire"`
		}
		return "scoop update entire/entire"
	}

	if releaseChannel(currentVersion) == installChannelNightly {
		return "curl -fsSL https://entire.io/install.sh | bash -s -- --channel nightly"
	}
	return "curl -fsSL https://entire.io/install.sh | bash"
}

func UpdateCommandForCurrentBinary(currentVersion string) string {
	if !canAutoInstall() {
		return downloadsURL
	}
	return updateCommand(currentVersion)
}

// printNotification prints the version update notification to the user.
func printNotification(w io.Writer, current, latest string) {
	fmt.Fprintf(w, "\nUpdate available! %s -> %s\nRelease notes: %s\n",
		displayVersion(current), displayVersion(latest), releaseNotesURL(latest))
}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := parseGitHubRelease([]byte(tt.body))
			if (err != nil) != tt.wantErr {
				t.Errorf("parseGitHubRelease() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			if got != tt.want {
				t.Errorf("parseGitHubRelease() = %q, want %q", got, tt.want)
			}
		})
	}
}

// brewUpgradeCmd is the install command produced for any brew-installed
// binary on a stable channel. Hoisted to a const so tests can reference
// it without tripping goconst on repeated string literals.
const brewUpgradeCmd = "brew upgrade --yes entire"

// scoopExecutablePath is the pre-rename `cli` app dir; scoopEntireExecutablePath
// is the renamed `entire` app dir. The Scoop update command is chosen by which
// app dir the binary runs from, not by version.
const scoopExecutablePath = `C:\Users\test\scoop\apps\cli\current\entire.exe`
const scoopEntireExecutablePath = `C:\Users\test\scoop\apps\entire\current\entire.exe`

// plainBinPath is a POSIX install under no recognized install manager.
const plainBinPath = "/usr/local/bin/entire"

// TestScoopAppName pins the signal the rename migration keys off. The ""
// results matter most: they are what keeps the `== "cli"` comparison in
// updateCommand from misfiring on a non-Scoop binary that happens to live in a
// directory named `cli`.
func TestScoopAppName(t *testing.T) {
	tests := []struct {
		name     string
		execPath func() (string, error)
		want     string
	}{
		{
			name:     "pre-rename cli app dir",
			execPath: func() (string, error) { return scoopExecutablePath, nil },
			want:     "cli",
		},
		{
			name:     "renamed entire app dir",
			execPath: func() (string, error) { return scoopEntireExecutablePath, nil },
			want:     "entire",
		},
		{
			name:     "non-scoop path in a cli directory",
			execPath: func() (string, error) { return `C:\tools\cli\entire.exe`, nil },
			want:     "",
		},
		{
			name:     "posix install",
			execPath: func() (string, error) { return plainBinPath, nil },
			want:     "",
		},
		{
			name:     "executable path unavailable",
			execPath: func() (string, error) { return "", errors.New("not found") },
			want:     "",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			original := executablePath
			executablePath = tt.execPath
			t.Cleanup(func() { executablePath = original })

			if got := scoopAppName(); got != tt.want {
				t.Errorf("scoopAppName() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestUpdateCommand(t *testing.T) {
	tests := []struct {
		name           string
		currentVersion string
		execPath       func() (string, error)
		want           string
	}{
		{
			name:           "homebrew stable cellar path uses brew command",
			currentVersion: "1.0.0",
			execPath:       func() (string, error) { return "/opt/homebrew/Cellar/entire/1.0.0/bin/entire", nil },
			want:           brewUpgradeCmd,
		},
		{
			name:           "homebrew stable cask path uses brew command",
			currentVersion: "1.0.0",
			execPath:       func() (string, error) { return "/opt/homebrew/bin/entire", nil },
			want:           brewUpgradeCmd,
		},
		{
			name:           "homebrew nightly path uses brew command",
			currentVersion: "1.0.1-nightly.202604101200.abc1234",
			execPath:       func() (string, error) { return "/opt/homebrew/bin/entire", nil },
			want:           "brew upgrade --yes entire@nightly",
		},
		{
			name:           "linuxbrew path",
			currentVersion: "1.0.0",
			execPath:       func() (string, error) { return "/home/linuxbrew/.linuxbrew/bin/entire", nil },
			want:           brewUpgradeCmd,
		},
		{
			name:           "mise path",
			currentVersion: "1.0.0",
			execPath:       func() (string, error) { return "/home/user/.local/share/mise/installs/entire/1.0.0/bin/entire", nil },
			want:           "mise upgrade entire",
		},
		{
			name:           "scoop entire app updates in place",
			currentVersion: "1.0.0",
			execPath:       func() (string, error) { return scoopEntireExecutablePath, nil },
			want:           "scoop update entire/entire",
		},
		{
			name:           "scoop cli app routes through package rename regardless of version",
			currentVersion: "1.0.0",
			execPath:       func() (string, error) { return scoopExecutablePath, nil },
			want:           `cmd.exe /D /C "scoop install entire/entire && scoop uninstall entire/cli && scoop reset entire"`,
		},
		{
			name:           "unknown path stable falls back to stable curl command",
			currentVersion: "1.0.0",
			execPath:       func() (string, error) { return plainBinPath, nil },
			want:           "curl -fsSL https://entire.io/install.sh | bash",
		},
		{
			name:           "unknown path nightly falls back to nightly curl command",
			currentVersion: "1.0.1-nightly.202604101200.abc1234",
			execPath:       func() (string, error) { return plainBinPath, nil },
			want:           "curl -fsSL https://entire.io/install.sh | bash -s -- --channel nightly",
		},
		{
			name:           "executable error falls back to stable curl command",
			currentVersion: "1.0.0",
			execPath:       func() (string, error) { return "", errors.New("not found") },
			want:           "curl -fsSL https://entire.io/install.sh | bash",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			original := executablePath
			executablePath = tt.execPath
			t.Cleanup(func() { executablePath = original })

			if got := updateCommand(tt.currentVersion); got != tt.want {
				t.Errorf("updateCommand() = %q, want %q", got, tt.want)
			}
		})
	}
}

func TestUpdateCommandForCurrentBinary(t *testing.T) {
	tests := []struct {
		name           string
		currentVersion string
		goos           string
		execPath       func() (string, error)
		want           string
	}{
		{
			name:           "known installer returns command",
			currentVersion: "1.2.3",
			goos:           goosWindows,
			execPath:       func() (string, error) { return scoopEntireExecutablePath, nil },
			want:           "scoop update entire/entire",
		},
		{
			name:           "windows unknown installer returns releases URL",
			currentVersion: "1.2.3",
			goos:           goosWindows,
			execPath:       func() (string, error) { return `C:\Program Files\Entire\entire.exe`, nil },
			want:           downloadsURL,
		},
		{
			name:           "non-windows unknown installer returns curl command",
			currentVersion: "1.2.3",
			goos:           "linux",
			execPath:       func() (string, error) { return plainBinPath, nil },
			want:           "curl -fsSL https://entire.io/install.sh | bash",
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			originalExecPath := executablePath
			executablePath = tt.execPath
			t.Cleanup(func() { executablePath = originalExecPath })

			originalGOOS := goos
			goos = tt.goos
			t.Cleanup(func() { goos = originalGOOS })

			if got := UpdateCommandForCurrentBinary(tt.currentVersion); got != tt.want {
				t.Errorf("UpdateCommandForCurrentBinary() = %q, want %q", got, tt.want)
			}
		})
	}
}

